def countPairs(nums: list[int], low: int, high: int) -> int:
    class TrieNode:
        def __init__(self):
            self.children = [None, None]
            self.count = 0
    def insert(root, val):
        node = root
        for b in range(16, -1, -1):
            bit = (val >> b) & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1
    def count_less_than(root, val, k):
        node = root
        res = 0
        for b in range(16, -1, -1):
            if not node: break
            v_bit = (val >> b) & 1
            k_bit = (k >> b) & 1
            if k_bit == 1:
                if node.children[v_bit]:
                    res += node.children[v_bit].count
                node = node.children[1 - v_bit]
            else:
                node = node.children[v_bit]
        return res
    def count_k(k):
        root = TrieNode()
        total = 0
        for x in nums:
            total += count_less_than(root, x, k)
            insert(root, x)
        return total
    return count_k(high + 1) - count_k(low)

